"""Illustrative low-pressure activities, not aptitude testing."""
ACTIVITIES = [
 {"id":"build-a-tool","title":"Invent a helpful tool","interest_tags":["technology","design","problem_solving"],"duration_minutes":15,"materials":"Paper and pencil","instructions":["Think of a small everyday frustration.","Sketch a tool that could make it easier.","Explain one change you would make after feedback."],"reflection_prompt":"Which part was most enjoyable: imagining, sketching or solving the problem?"},
 {"id":"nature-detective","title":"Nature detective","interest_tags":["environment","science"],"duration_minutes":15,"materials":"Notebook","instructions":["Observe a plant or natural feature safely.","Write three questions about what you saw.","Suggest a gentle way to find out more."],"reflection_prompt":"What did you enjoy about observing and asking questions?"},
 {"id":"story-studio","title":"Story studio","interest_tags":["writing","arts"],"duration_minutes":15,"materials":"Paper or text editor","instructions":["Invent a character facing an everyday problem.","Write a short beginning, middle and ending.","Give your story a title."],"reflection_prompt":"Was creating characters, words or ideas the best part?"},
 {"id":"community-ideas","title":"Community ideas board","interest_tags":["helping_people","business"],"duration_minutes":20,"materials":"Paper or sticky notes","instructions":["Choose a small local challenge.","List who it affects and what they might need.","Sketch two friendly ways to help."],"reflection_prompt":"Did listening to needs or planning solutions interest you more?"},
 {"id":"pattern-hunt","title":"Pattern hunt","interest_tags":["mathematics","problem_solving"],"duration_minutes":10,"materials":"Paper and pencil","instructions":["Create a repeating number or shape pattern.","Ask someone to predict the next step.","Show two ways to explain your reasoning."],"reflection_prompt":"What did you like about discovering or explaining a pattern?"},
 {"id":"team-practice","title":"Team practice designer","interest_tags":["sports","helping_people"],"duration_minutes":15,"materials":"Paper","instructions":["Choose a simple safe movement skill.","Design a fun practice activity for beginners.","Add a way for everybody to participate."],"reflection_prompt":"What was most satisfying about helping others practise?"}
]
def get_activities(interest: str = ""):
    interest = interest.strip().casefold()
    return [{**a, "interest_tags": list(a["interest_tags"]), "instructions": list(a["instructions"]), "illustrative": True} for a in ACTIVITIES if not interest or interest in a["interest_tags"]]
